export function createUploadServer() {
  /** @type {Map<string, {ranges: Map<number, Buffer>, total: number|null, log: number[]}>} */
  const uploads = new Map();
  const pendingFails = new Set(); // `${id}@${start}`
  let assembled = new Map();

  function ensure(id, total) {
    let u = uploads.get(id);
    if (!u) { u = { ranges: new Map(), total: null, log: [] }; uploads.set(id, u); }
    if (total != null && u.total == null) u.total = total;
    return u;
  }

  function contiguous(u) {
    let pos = 0;
    while (u.ranges.has(pos)) pos += u.ranges.get(pos).length;
    return pos;
  }

  function tryAssemble(id, u) {
    if (assembled.has(id)) return assembled.get(id);
    const have = contiguous(u);
    if (u.total == null || have < u.total) return null;
    const parts = [];
    let pos = 0;
    while (pos < u.total) {
      const b = u.ranges.get(pos);
      if (!b) return null;
      parts.push(b); pos += b.length;
    }
    const full = Buffer.concat(parts);
    assembled.set(id, full);
    return full;
  }

  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      const id = url.searchParams.get('id');

      if (req.method === 'GET' && url.pathname === '/status') {
        if (!id) return sendJson(res, 400, { error: 'missing id' });
        const u = uploads.get(id);
        return sendJson(res, u ? 200 : 404, { received: u ? contiguous(u) : 0 });
      }

      if (req.method === 'PUT' && url.pathname === '/upload') {
        if (!id) return sendJson(res, 400, { error: 'missing id' });
        const cr = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(req.headers['content-range'] || '');
        if (!cr) return sendJson(res, 400, { error: 'missing/invalid Content-Range' });
        const start = Number(cr[1]), end = Number(cr[2]), total = Number(cr[3]);
        const body = await collect(req);
        if (body.length !== end - start + 1) return sendJson(res, 400, {...});

        const u = ensure(id, total);
        const failKey = `${id}@${start}`;
        if (pendingFails.has(failKey)) {
          pendingFails.delete(failKey);
          return sendJson(res, 500, { error: 'simulated failure' });
        }
        u.ranges.set(start, body); // wait: need copy? collect returns concat Buffer, safe.
        u.log.push(start);
        tryAssemble(id, u);
        return sendJson(res, 200, { received: contiguous(u) });
