        const u = uploads.get(id);
        const full = u ? assembled.get(id) : null;
        if (!full) return sendJson(res, 404, { error: 'not ready' });
        res.writeHead(200, { 'content-type': 'application/octet-stream' });
        return res.end(full);
      }

      sendJson(res, 404, { error: 'not found' });
    } catch (err) { sendJson(res, 500, { error: String(err) }); }
  });

  return {
    server,
    listen(port = 0) { return new Promise(r => server.listen(port, () => r(server.address().port))); },
    forceFailOnce(id, index, chunkSize) { pendingFails.add(`${id}@${index * chunkSize}`); },
    chunkLog(id) { return [...(uploads.get(id)?.log ?? [])]; },
    receivedBytes(id) { const u = uploads.get(id); return u ? contiguous(u) : 0; },
    close() { return new Promise(r => { server.close(() => r()); if (typeof server.closeAllConnections === 'function') server.closeAllConnections(); }); },
  };
}
