/**
 * Upload `buffer` in chunks with resume support.
 *
 * - Before sending anything, asks GET `<endpoint>/status?id=` for the server's
 *   received-bytes offset and skips chunks that are already fully confirmed.
 * - PUTs each remaining chunk to `<endpoint>/upload?id=` with a
 *   `Content-Range: bytes <start>-<end>/<total>` header.
 * - Retries a failed chunk up to `maxRetries` (default 2) times.
 * - Reports progress via onProgress(confirmedBytes), where confirmedBytes counts
 *   the resumed offset plus every byte of chunks acknowledged by the server.
 *
 * Returns `{ id, size, resumedFrom }`.
 */
export async function upload(buffer, options = {}) {
  const {
    chunkSize = 64 * 1024,
    endpoint,
    onProgress,
    maxRetries = 2,
    id = defaultId(buffer),
  } = options;

  if (!Buffer.isBuffer(buffer)) throw new TypeError('upload expects a Buffer');
  if (!endpoint) throw new TypeError('upload requires an endpoint');
  if (!Number.isInteger(chunkSize) || chunkSize <= 0) throw new RangeError('chunkSize must be a positive integer');

  const base = String(endpoint).replace(/\/+$/, '');

  // --- resume: ask the server how much it already has -----------------------
  let offset = 0;
  try {
    const res = await fetch(`${base}/status?id=${encodeURIComponent(id)}`);
    if (res.ok || res.status === 404) {
      const body = await res.json();
      offset = Math.min(Number(body.received) || 0, buffer.length);
    }
  } catch {
    offset = 0; // unreachable status endpoint: start over rather than fail
  }

  let confirmed = offset;
  onProgress?.(confirmed);

  // --- one chunk PUT with retry ---------------------------------------------
  const putChunk = async (start, end, attempt = 0) => {
    let res;
    try {
      res = await fetch(`${base}/upload?id=${encodeURIComponent(id)}`, {
        method: 'PUT',
        headers: {
          'content-type': 'application/octet-stream',
          'content-range': `bytes ${start}-${end - 1}/${buffer.length}`,
        },
        body: buffer.subarray(start, end),
      });
    } catch (err) {
      if (attempt < maxRetries) return putChunk(start, end, attempt + 1);
      throw new Error(`chunk ${start}-${end - 1} failed after ${maxRetries + 1} attempts: ${err.message}`);
    }
    if (!res.ok) {
      // Drain so the socket can be reused before retrying.
      await res.arrayBuffer().catch(() => {});
      if (attempt < maxRetries) return putChunk(start, end, attempt + 1);
      throw new Error(`chunk ${start}-${end - 1} failed after ${maxRetries + 1} attempts: HTTP ${res.status}`);
    }
    await res.arrayBuffer().catch(() => {});
  };

  // --- sequential chunk loop, skipping already-confirmed bytes ---------------
  for (let start = 0; start < buffer.length; start += chunkSize) {
    const end = Math.min(start + chunkSize, buffer.length);
    if (end <= offset) continue; // fully confirmed by a previous session
    await putChunk(start, end);
    confirmed = end;
    onProgress?.(confirmed);
  }

  return { id, size: buffer.length, resumedFrom: offset };
}

/** Deterministic upload id derived from the content, so restarting an upload
 *  of the same buffer naturally resumes the same server-side session. */
