test('full upload matches source buffer byte-for-byte (hash compare)', async () => {
  // Length deliberately NOT a multiple of chunkSize to exercise the short tail chunk.
  const src = crypto.randomBytes(3 * CHUNK + 12345);
  const id = 'full-upload';
  const progress = [];

  const result = await upload(src, {
    chunkSize: CHUNK,
    endpoint: base,
    id,
    onProgress: (bytes) => progress.push(bytes),
  });

  assert.equal(result.id, id);
  assert.equal(result.size, src.length);
  assert.equal(result.resumedFrom, 0);

  const stored = await serverFile(id);
  assert.equal(stored.length, src.length);
  assert.equal(sha256(stored), sha256(src));

  // Progress reports bytes confirmed: monotonic and ending at the full size.
  for (let i = 1; i < progress.length; i++) assert.ok(progress[i] > progress[i - 1]);
