test('simulated restart resumes from the server offset instead of resending everything', async () => {
  const src = crypto.randomBytes(4 * CHUNK);
  const id = 'resume-test';
  const cs = CHUNK;

  // --- "previous session": only the first two chunks ever made it ---
  for (let i = 0; i < 2; i++) {
    const start = i * cs;
    const end = Math.min(start + cs, src.length) - 1;
    const res = await fetch(`${base}/upload?id=${id}`, {
      method: 'PUT',
      headers: { 'content-range': `bytes ${start}-${end}/${src.length}` },
      body: src.subarray(start, end + 1),
    });
    assert.equal(res.status, 200);
  }
  assert.equal(srv.receivedBytes(id), 2 * cs);

  // --- restart with a fresh client call ---
  const result = await upload(src, { chunkSize: cs, endpoint: base, id });
  assert.equal(result.resumedFrom, 2 * cs, 'client resumed at the server-reported offset');

  // Prove nothing before offset 2*cs was resent: chunks 0 and 1 each appear
  // in the received log exactly once, from the manual phase above.
  const log = srv.chunkLog(id);
  assert.deepEqual(
    log.filter((start) => start < 2 * cs),
    [0, cs],
  );

  // Remaining chunks sent exactly once, in order.
  const rest = log.filter((start) => start >= 2 * cs);
  assert.deepEqual(rest, [2 * cs, 3 * cs]);

  const stored = await serverFile(id);
  assert.equal(sha256(stored), sha256(src));
